% Variable Status Component% var_stat.pl%bounds(lower_bound, upper_bound)%range(range_sort, range)%ranges([r1, r2, ...])%prop(property_sort, value)%props([p1, p2, ...])%var_stat(var_name, [property1, property2, ..], [range1, range2, ...])new_var(Name, var_stat(Name, [], [])).new_var(Name, Properties, var_stat(Name, Properties, [])).new_var(Name, Properties, Ranges, var_stat(Name, Properties, Ranges)).add_property(var_stat(Name, Props, Ranges), Property_To_Add,              var_stat(Name, [Property_To_Add|Props], Ranges)).add_range(var_stat(Name, Props, Ranges), Range_To_Add,          var_stat(Name, Props, [Range_To_Add|Ranges])).        update_range([range(Range_Sort, _) | Remainder_Of_Ranges],             range(Range_Sort, New_Bounds),             [range(Range_Sort, New_Bounds) | Remainder_Of_Ranges]).update_range([Not_Range_Sort | Remainder_Of_Ranges], Range_To_Update,             [Not_Range_Sort | Updated_Range_List]) :-    update_range(Remainder_Of_Ranges, Range_To_Update, Updated_Range_List).                                                             